<?php declare(strict_types=1);

namespace KboPublicSearch\Core\Reply;

use KboPublicSearch\Core\Type\Primitive\Date;

/** The reply header KBO sends with every answer. */
final readonly class ReplyContext
{
    /** @internal */
    public function __construct(
        /** The identifier the SDK sent in RequestContext > Id. */
        public string $requestId,
        /** A UUID generated by KBO. */
        public string $replyId,
        public ReplyStatus $status,
        /** The raw status code, kept even when $status is Unknown. */
        public string $statusCode,
        /** KBO's English description of the status. */
        public string $statusDescription,
        /** The number of requests left today, when KBO reports it. */
        public ?int $accountBalance,
        /** The date the data reflects; null while KBO is refreshing (~00:30-02:00). */
        public ?Date $snapshotDate,
    ) {}

    /** Whether this reply was deducted from the daily request quota. */
    public function charged(): bool
    {
        return $this->status->charged();
    }
}
